# %% ../nbs/00_core.ipynb #740e3f87
def motif_occurrences(encoded_library, pattern):
    """Which motifs each sequence contains, as parallel `(sequence index, motif code)` arrays.

    Both strands are scanned and the result is reduced to one entry per sequence per motif, so
    a motif occurring several times in one sequence -- or once on each strand -- is counted
    once. Where a pattern is self-reverse-complementary the two spellings of a site are folded
    onto one code first, so `GAGACC` and `GGTCTC` come back as a single motif rather than two
    rows carrying identical statistics. Windows containing a non-ACGT base, or running off the
    end of a short sequence, are dropped: both carry the out-of-range code that
    `_pattern_window_codes` assigns.

    Returns:
        (seq_idx, motif_codes): equal-length int arrays. `seq_idx` is non-decreasing, so the
        pairs come out grouped by sequence.
    """
    fwd, rc = encoded_library
    n_codes = 4 ** (pattern[0] + pattern[2])
    codes = np.concatenate([_pattern_window_codes(fwd, pattern),
                            _pattern_window_codes(rc, pattern)], axis=1)
    if pattern_is_self_rc(pattern):
        # One site, two spellings, both in this code space -- fold each onto the smaller of the
        # pair. Rejected windows keep their out-of-range code: they are not in the table, so
        # they are held out of the lookup and passed through untouched.
        table = rc_code_table(pattern)
        inside = codes < n_codes
        codes = np.where(inside, np.minimum(codes, table[np.where(inside, codes, 0)]), codes)
    codes.sort(axis=1)                                  # repeats become adjacent
    keep = codes < n_codes                              # drop rejected windows
    keep[:, 1:] &= codes[:, 1:] != codes[:, :-1]        # drop repeats within a sequence
    return np.nonzero(keep)[0], codes[keep]

# %% ../nbs/00_core.ipynb #9444d51e
def _motif_totals(seq_idx, motif_codes, fc_values, log2FC_thr, n_codes):
    """Per motif code: sequences carrying it, how many of those are depleted, the sum of their
    log2FC, and the index of the first sequence that carries it.

    Sums rather than means, because `np.bincount` adds; the means are taken once at the end.
    """
    seq_fc = fc_values[seq_idx]
    n_seqs = np.bincount(motif_codes, minlength=n_codes)
    n_depleted = np.bincount(motif_codes, weights=seq_fc < log2FC_thr, minlength=n_codes)
    fc_sum = np.bincount(motif_codes, weights=seq_fc, minlength=n_codes)
    first_seq = np.full(n_codes, len(fc_values))
    np.minimum.at(first_seq, motif_codes, seq_idx)
    return n_seqs, n_depleted, fc_sum, first_seq

# %% ../nbs/00_core.ipynb #ec3f32e4
def scan_pattern(encoded_library, pattern, fc_values, log2FC_thr=-1, parallel=True):
    """Steps A and B for one pattern: per motif code, how many sequences carry it, how many of
    those are depleted, the sum of their log2FC, and the first sequence that carries it.

    The compiled kernel from `randseq.fast` when numba is installed, `motif_occurrences` and
    `_motif_totals` otherwise -- the same four arrays either way. Every count the pipeline makes
    of "the plasmids carrying a motif" comes from here, so no two steps can disagree on it.
    """
    fc_values = np.asarray(fc_values, dtype=float)
    if _fast.HAVE_NUMBA:
        return _fast.pattern_totals(encoded_library, pattern, fc_values, log2FC_thr,
                                    parallel=parallel)
    seq_idx, motif_codes = motif_occurrences(encoded_library, pattern)
    return _motif_totals(seq_idx, motif_codes, fc_values, log2FC_thr,
                         4 ** (pattern[0] + pattern[2]))


def _scores_from_totals(totals, pattern, codes, background_rate):
    """Step C for the given motif codes: the reported statistics, ordered by first sequence."""
    n_seqs, n_depleted, fc_sum, first_seq = totals
    codes = codes[np.argsort(first_seq[codes], kind="stable")]
    frac = n_depleted[codes] / n_seqs[codes]
    return pd.DataFrame({
        'motif': decode_motif_codes(codes, pattern),
        'fraction_depleted': frac,
        'num_sequences': n_seqs[codes],
        'avg_log2fc': fc_sum[codes] / n_seqs[codes],
        # P(at least this many of n depleted | null), against THIS sample's background
        # rate rather than a constant -- see `01_utils`.
        'p_value': motif_pvalues(n_seqs[codes], frac, background_rate),
    })


def get_pattern_scores(encoded_library, fc_values, pattern, log2FC_thr=-1,
                       background_rate=None, parallel=True):
    """
    Scores every motif of `pattern` found in the library, on both strands.

    Steps A, B and C above: find the (sequence, motif) pairs, total them per motif, and turn
    the totals into the reported statistics. A motif is counted once per sequence that contains
    it on either strand. `tests/reference_scan.py` holds a readable implementation of the same
    scan, and `tests/test_reference_scan.py` requires the two to give identical tables.

    When numba is installed, steps A and B run as one compiled pass instead (`randseq.fast`),
    which returns the same totals; `tests/test_fast_scan.py` requires the two paths to agree.

    Args:
        encoded_library (tuple): (fwd, rc) arrays from `encode_library`.
        fc_values (list or np.ndarray): log2FC of each sequence, in library order.
        pattern (tuple): (d1, spacer, d2) motif pattern.
        log2FC_thr (float): a sequence is depleted when its log2FC is below this value.
        background_rate (float): the null depletion rate the p-value is taken against;
            defaults to this library's own.
        parallel (bool): let the compiled path use numba's threads. Ignored on the numpy path.

    Returns:
        pd.DataFrame: one row per motif with 'motif', 'fraction_depleted',
            'num_sequences', 'avg_log2fc' and 'p_value', ordered by the first sequence that
            contains the motif.
    """
    fc_values = np.asarray(fc_values, dtype=float)
    totals = scan_pattern(encoded_library, pattern, fc_values, log2FC_thr, parallel)   # A + B
    if background_rate is None:
        # The one definition of the null rate, shared with `annotate_significance`: the q-value
        # correction recognises a reported motif's test by its p-value, so the two must agree to
        # the last bit.
        background_rate = background_depletion_rate(fc_values, log2FC_thr)
    return _scores_from_totals(totals, pattern, np.flatnonzero(totals[0]), background_rate)  # C

# %% ../nbs/00_core.ipynb #0b75ece4
def process_single_flexible_pattern(
    current_flex_pattern,
    encoded_library,
    fc_values_for_flexible_analysis,
    flexible_motif_log2fc_thr,
    flexible_motif_score_thr,
    flexible_motif_min_support,
    parallel=True,
):
    """
    Scores all motifs of one flexible pattern and keeps the candidates with
    fraction_depleted >= flexible_motif_score_thr and num_sequences >= flexible_motif_min_support.

    Args:
        current_flex_pattern (tuple): (d1, spacer, d2) motif pattern.
        encoded_library (tuple): (fwd, rc) arrays from `encode_library` (sequences with context).
        fc_values_for_flexible_analysis (list): log2FC of each sequence, in library order.
        flexible_motif_log2fc_thr (float): log2FC below which a sequence counts as depleted.
        flexible_motif_score_thr (float): minimum fraction_depleted (inclusive, `>=`).
        flexible_motif_min_support (int): minimum number of sequences (inclusive, `>=`).
        parallel (bool): passed to `get_pattern_scores`; False inside a pool worker.

    Returns:
        (pd.DataFrame, np.ndarray, tuple): the surviving candidates -- 'motif',
            'fraction_depleted', 'num_sequences', 'avg_log2fc' and 'pattern' (the pattern as a
            string) -- the p-value of *every* motif that had enough support to be a test,
            survivor or not, and the pattern's totals from `scan_pattern`, so that later steps
            can look motifs of this pattern up rather than scan it again.

    Both are returned because the Benjamini-Hochberg correction needs the full set of tests, and
    only this function ever sees it: the candidates that fail the score threshold are discarded
    here, but they were still tested, and a correction that ignored them would be wrong.
    """
    fc = np.asarray(fc_values_for_flexible_analysis, dtype=float)
    totals = scan_pattern(encoded_library, current_flex_pattern, fc,
                          flexible_motif_log2fc_thr, parallel)
    n_seqs, n_depleted = totals[0], totals[1]
    background = background_depletion_rate(fc, flexible_motif_log2fc_thr)
    # Only the candidates are turned into strings; the tests stay arrays. A pattern has up to
    # 4**8 motifs present, and decoding every one of them was most of this step's time.
    tested = np.flatnonzero(n_seqs >= max(flexible_motif_min_support, 1))
    frac = n_depleted[tested] / n_seqs[tested]
    kept = _scores_from_totals(totals, current_flex_pattern,
                               tested[frac >= flexible_motif_score_thr], background)
    kept['pattern'] = str(current_flex_pattern)
    return kept, motif_pvalues(n_seqs[tested], frac, background), totals

# %% ../nbs/00_core.ipynb #b4ea79aa
def variant_profile(motifs, pattern, encoded, fc, log2fc_thr, totals=None):
    """Support and depletion score for each of a set of related motifs.

    Read off the pattern's totals from `scan_pattern` -- the counts step 2 makes -- so a
    variant is scored exactly as it would have been had its pattern been scanned there.

    Args:
        motifs (list): motif strings, all of the same `pattern`.
        pattern (tuple): the `(d1, spacer, d2)` shape they share.
        encoded (tuple): `(fwd, rc)` from `encode_library`.
        fc (np.ndarray): log2 fold change per library sequence, in the same order.
        log2fc_thr (float): a plasmid is depleted below this.
        totals (dict): totals by canonical pattern, for this library, `fc` and threshold.
            Shared across calls, it makes every pattern scanned at most once, and the patterns
            step 2 scanned never again. Filled in place.

    Returns:
        list: one `(motif, n_plasmids, score)` per motif, in the order given. A motif that has
        no code (an IUPAC base, or a defined base in the spacer) gets `n=0` and a score of `nan`.
    """
    totals = {} if totals is None else totals
    canon = canonical_pattern(pattern)
    if canon not in totals:
        totals[canon] = scan_pattern(encoded, canon, fc, log2fc_thr)
    n_seqs, n_depleted = totals[canon][0], totals[canon][1]
    mirrored = pattern[1] != 0 and tuple(pattern) != canon    # spelled on the other strand
    rc_table = rc_code_table(canon) if pattern_is_self_rc(canon) else None
    out = []
    for m in motifs:
        code = encode_motif(revcomp(m) if mirrored else m, canon)
        if code is not None and rc_table is not None:
            code = min(code, int(rc_table[code]))             # the fold step 2 applied
        n = int(n_seqs[code]) if code is not None else 0
        out.append((m, n, float(n_depleted[code] / n) if n else float("nan")))
    return out

# %% ../nbs/00_core.ipynb #f0204ef3
def verdict(profile, score_thr, min_support):
    """Call a variant profile 'mixture', 'genuine' or 'unknown'.

    Args:
        profile (list): `(motif, n, score)` triples, from `variant_profile`.
        score_thr (float): the depletion score a candidate had to reach to be here.
        min_support (int): a variant on fewer plasmids than this is not judged.

    Returns:
        tuple: the verdict, and the spread across judgeable variants (`None` when fewer than
        two can be judged).
    """
    judged = [s for _, n, s in profile if n >= min_support]
    if len(judged) < 2:
        return "unknown", None
    spread = max(judged) - min(judged)
    bimodal = any(s < score_thr for s in judged) and spread >= score_thr
    return ("mixture" if bimodal else "genuine"), spread

# %% ../nbs/00_core.ipynb #a7b0c0fa
def _undefined_positions(motif, pattern):
    """Each undefined position worth testing on a candidate, as (four variants, their pattern)."""
    d1, spacer, d2 = pattern
    width = d1 + spacer + d2
    jobs = [([b + motif for b in "ACGT"], (width + 1, 0, 0) if spacer == 0 else (d1 + 1, spacer, d2)),
            ([motif + b for b in "ACGT"], (width + 1, 0, 0) if spacer == 0 else (d1, spacer, d2 + 1))]
    if spacer:
        p = d1
        jobs.append(([motif[:p] + b + motif[p + 1:] for b in "ACGT"],
                     (d1 + 1 + d2, 0, 0) if spacer == 1 else (d1 + 1, spacer - 1, d2)))
        if spacer > 1:
            p = d1 + spacer - 1
            jobs.append(([motif[:p] + b + motif[p + 1:] for b in "ACGT"], (d1, spacer - 1, d2 + 1)))
    return jobs

# %% ../nbs/00_core.ipynb #b04daf67
def is_mixture(motif, pattern, encoded_library, fc_values, log2fc_thr=-1,
               score_thr=0.5, min_support=5, totals=None):
    """Does fixing one undefined position split this motif's plasmids into sites and non-sites?

    Args:
        motif (str): the candidate.
        pattern (tuple): its `(d1, spacer, d2)` shape.
        encoded_library (tuple): `(fwd, rc)` from `encode_library`.
        fc_values (np.ndarray): log2 fold change per library sequence.
        log2fc_thr (float), score_thr (float), min_support (int): as elsewhere in the step.
        totals (dict): shared pattern totals, as for `variant_profile`.

    Returns:
        bool: True when some position's four bases are bimodal.
    """
    for variants, vpat in _undefined_positions(motif, pattern):
        if sum(vpat) > encoded_library[0].shape[1]:  # the padded motif is wider than the insert
            continue
        if verdict(variant_profile(variants, vpat, encoded_library, fc_values, log2fc_thr,
                                   totals), score_thr, min_support)[0] == "mixture":
            return True
    return False

# %% ../nbs/00_core.ipynb #b2a6b3be
def is_extension(specific, general):
    """Is `specific` the motif `general` with one more defined base, on either strand?

    The extra base sits one past an end of `general` or at an edge of its spacer -- the
    positions `_undefined_positions` tests. Both strands are checked because every pattern is
    searched in one canonical form, so adding a base to a motif's longer side can turn its shape
    into the mirror form, which the scan writes on the other strand: `TACNNNNGTGA` is
    `CACNNNNGTA` with a base added on the left.
    """
    defined = lambda m: len(m) - m.count("N")
    return defined(specific) == defined(general) + 1 and find_broad_in_specific(specific, general)


def filter_redundant_patterns(df, log2fc_series, left_context, right_context,
                              log2fc_thr=-1, score_thr=0.5, min_support=5,
                              encoded=None, totals=None):
    """Keep one description per site, by two rules.

    1. **A mixture is not a site.** A candidate is dropped when fixing one position next to it
       splits its plasmids into depleting and not (`is_mixture`).
    2. **A one-base extension of a site is redundant.** A candidate is dropped when it is a
       candidate that survived rule 1 with one more defined base (`is_extension`): rule 1 found
       that site's neighbouring positions carry nothing, so pinning one adds nothing.

    Neither rule depends on the order the candidates arrive in.

    Args:
        df (pd.DataFrame): candidates, with 'motif' and 'pattern'.
        log2fc_series (pd.Series): log2 fold change, indexed by insert sequence.
        left_context (str), right_context (str): the vector flanks.
        log2fc_thr (float): a plasmid is depleted below this.
        score_thr (float): the score a candidate had to reach, reused as the bar a variant must
            clear and as the spread that marks a profile bimodal.
        min_support (int): a variant on fewer plasmids than this is not judged.
        encoded (tuple): the library from `encode_library`, if the caller already has it.
        totals (dict): shared pattern totals, as for `variant_profile`.

    Returns:
        pd.DataFrame: `df` without the redundant rows, in the original row order.
    """
    if df.empty:
        return df
    motifs = df["motif"].tolist()
    pats = []
    for pat in (df["pattern"] if "pattern" in df.columns else [None] * len(df)):
        try:
            pats.append(tuple(ast.literal_eval(pat)) if isinstance(pat, str) else (tuple(pat) if pat else None))
        except Exception:
            pats.append(None)
    if encoded is None:
        encoded = encode_library(get_lib_seq_context(log2fc_series.index.tolist(),
                                                     left_context, right_context))
    totals = {} if totals is None else totals
    fc = log2fc_series.to_numpy()

    # Rule 1. A candidate whose pattern is unknown cannot be tested, and stays.
    survivors = [k for k in range(len(df)) if pats[k] is None or not is_mixture(
        motifs[k], pats[k], encoded, fc, log2fc_thr, score_thr, min_support, totals)]

    # Rule 2. A one-base extension has exactly one more defined base, so each survivor is only
    # compared with the survivors one base shorter, not with every other candidate.
    by_defined = defaultdict(list)
    for k in survivors:
        by_defined[len(motifs[k]) - motifs[k].count("N")].append(k)
    keep = [k for k in survivors
            if not any(is_extension(motifs[k], motifs[j])
                       for j in by_defined[len(motifs[k]) - motifs[k].count("N") - 1])]
    return df.iloc[keep]

# %% ../nbs/00_core.ipynb #96db3fc5
def fixed_motif_presence(log2fc_series, fixed_motifs_df):
    """Boolean (n_sequences, n_fixed): does sequence i carry fixed motif j at its offset?

    The offset is read from the motif's own anchoring end, so this is correct on a library of
    ragged inserts: a right-anchored motif is looked for at the same distance from the end of
    every sequence, however long that sequence is.
    """
    seqs = list(log2fc_series.index)
    if fixed_motifs_df is None or len(fixed_motifs_df) == 0:
        return np.zeros((len(seqs), 0), dtype=bool)
    columns = []
    for row in fixed_motifs_df.itertuples():
        pos, n = int(row.position), int(row.length)
        anchor = getattr(row, 'anchor', 'left')
        if anchor == 'left':
            columns.append(np.array([s[pos:pos + n] == row.motif for s in seqs], dtype=bool))
        else:
            columns.append(np.array([len(s) >= pos + n and
                                     s[len(s) - pos - n:len(s) - pos] == row.motif
                                     for s in seqs], dtype=bool))
    return np.column_stack(columns)


def fixed_motif_labels(fixed_motifs_df):
    """`MOTIF@L4` / `MOTIF@R0` -- the motif, the anchoring end, and the offset from it."""
    if fixed_motifs_df is None or len(fixed_motifs_df) == 0:
        return []
    return [f"{r.motif}@{getattr(r, 'anchor', 'left')[0].upper()}{int(r.position)}"
            for r in fixed_motifs_df.itertuples()]

# %% ../nbs/00_core.ipynb #194b899f
def filter_explained_candidates(candidates_df, log2fc_series, left_context, right_context,
                                log2fc_thr=-1, score_thr=0.7, min_support=3,
                                fixed_motifs_df=None, encoded=None):
    """Drop candidates whose depletion is fully accounted for by stronger candidates.

    Candidates are taken strongest first. Each `X` is restricted to the plasmids that carry
    **none** of the stronger candidates still standing; if what is left no longer reaches
    `score_thr`, `X`'s score was borrowed and `X` is removed. Otherwise it stands, and its own
    plasmids join the set later candidates are tested against.

    The test is against the *union* of the stronger survivors, not against each in turn. A
    description that overlaps several co-occurring sites can keep a depleted residue against
    every one of them separately while carrying no plasmid that none of them explains -- on the
    older JJ1886 run, `CCACNNNAGTA` had 55 carriers, all depleted, every one of which also
    carried one of the four real sites, and a pairwise test kept it.

    The test is on the **collapse**, not on the size of what is left: a motif whose residue is
    empty has nothing of its own, and one whose residue still depletes keeps its claim however
    few plasmids it rests on. Scoring a residue against `min_support` instead would decide
    near-complete overlaps on which description happened to score a hundredth higher, since
    neither residue would be large enough to judge.

    No threshold is introduced: the test re-applies `score_thr` to the conditional set.

    Args:
        candidates_df: surviving candidates, with 'motif' and (optionally) 'pattern' columns.
        log2fc_series: the full log2FC series, indexed by sequence.
        left_context, right_context: the vector sequence flanking the insert.
        log2fc_thr: a plasmid is depleted below this.
        score_thr: fraction of plasmids that must still be depleted for a candidate to stand
            on its own.
        min_support: unused by the residue test, which is relative -- the candidate's support
            was already established when it became a candidate. Accepted so that the step takes
            the same thresholds as the rest of the pipeline.
        fixed_motifs_df: the fixed-position motifs, offered as additional explainers. They can
            explain a candidate but are never themselves dropped, because they are not being
            reported as sites, and they never explain a candidate they merely tie with. This matters when the real site cannot be written as any scanned
            pattern: nothing in the candidate set can then account for the junction plasmids,
            and every candidate overlapping them borrows depletion that has no owner.

    Returns:
        (kept_df, explanations) where explanations maps a dropped motif to
        (explaining motif, plasmids left, score on them).
    """
    if candidates_df.empty:
        return candidates_df, {}
    if len(candidates_df) < 2 and (fixed_motifs_df is None or len(fixed_motifs_df) == 0):
        return candidates_df, {}     # nothing that could explain anything

    motifs = candidates_df['motif'].tolist()
    if 'pattern' in candidates_df.columns:
        patterns = []
        for p in candidates_df['pattern']:
            try:
                patterns.append(tuple(ast.literal_eval(p)) if isinstance(p, str) else tuple(p))
            except (ValueError, SyntaxError):
                patterns.append(None)
    else:
        patterns = [None] * len(motifs)

    if encoded is None:
        encoded = encode_library(
            get_lib_seq_context(log2fc_series.index.tolist(), left_context, right_context))
    presence, handled = motif_presence_matrix(encoded, motifs, patterns)
    for j in np.flatnonzero(~handled):
        presence[:, j] = _get_filter_for_motif(
            log2fc_series, motifs[j], left_context, right_context).to_numpy()

    # Fixed-position motifs join as explainer-only columns, after the candidates, so an
    # index below n_candidates is droppable and one at or above it is not.
    n_candidates = len(motifs)
    presence = np.hstack([presence, fixed_motif_presence(log2fc_series, fixed_motifs_df)])
    motifs = motifs + fixed_motif_labels(fixed_motifs_df)

    fc = log2fc_series.to_numpy()
    strength = []
    for j in range(len(motifs)):
        v = fc[presence[:, j]]
        strength.append(((v < log2fc_thr).mean() if len(v) else 0.0,
                         len(v),
                         motifs[j]))
    # Strongest first: highest depletion fraction, then MOST plasmids. Support breaks the tie,
    # not mean log2FC, because a shadow is a subset of its parent's plasmids, and a subset
    # picked out by the extra bases it requires tends to keep the most depleted of them -- so on
    # mean log2FC a shadow systematically outranks the site it came from, is never tested against
    # it, and survives. On the older JJ1886 run CCACNNNAGTA (55 plasmids, mean -4.85) sorted above
    # its parent ATACNNNNGTG (192, -4.76) and stood, although every one of its plasmids carried a
    # known site. A subset can never have more plasmids than the set it is drawn from.
    # The motif string is the final tie-break so the order, and therefore the outcome, is a
    # function of the candidates rather than of the row order they arrive in.
    # On a tie, a candidate outranks a fixed-position motif. A junction-formed site can be
    # described by a flexible motif covering exactly the fixed motif's plasmids, in which case
    # the two tie on every statistic -- and the fixed motif must not be allowed to explain it
    # away, because the fixed motif is evidence about the junction while the candidate is the
    # answer. Without this the label string decides, and the real call survives or is discarded
    # depending on how it happens to sort.
    order = sorted(range(len(motifs)),
                   key=lambda j: (-strength[j][0], -strength[j][1],
                                  1 if j >= n_candidates else 0, strength[j][2]))

    explanations = {}
    covered = np.zeros(presence.shape[0], dtype=bool)   # plasmids a stronger survivor carries
    standing = []                                        # those survivors, strongest first
    for x in order:
        if x < n_candidates:
            alone = presence[:, x] & ~covered
            n = int(alone.sum())
            v = fc[alone]
            still = float((v < log2fc_thr).mean()) if n else 0.0
            if n == 0 or still < score_thr:
                # Name the survivor that accounts for most of X's plasmids, and say how many
                # others it took. A shadow cannot explain anything, so it never joins `covered`.
                shared = [(int((presence[:, x] & presence[:, y]).sum()), -k, y)
                          for k, y in enumerate(standing)]
                shared = [s for s in shared if s[0] > 0]
                if shared:
                    label = motifs[max(shared)[2]] + (
                        f" + {len(shared) - 1} more" if len(shared) > 1 else "")
                else:                    # fails on its own plasmids; nothing to blame
                    label = "(no stronger motif)"
                explanations[x] = (label, n, still)
                continue
        # A fixed motif explains but is never dropped; a candidate that stood joins it.
        covered |= presence[:, x]
        standing.append(x)

    keep = [j for j in range(n_candidates) if j not in explanations]
    return (candidates_df.iloc[keep],
            {motifs[x]: v for x, v in explanations.items()})

# %% ../nbs/00_core.ipynb #f9ba37dc
def bimodality_coefficient(values):
    """Sarle's bimodality coefficient: (skew^2 + 1) / (kurtosis + 3(n-1)^2/((n-2)(n-3))).

    Above 5/9 the distribution is more bimodal than a uniform one. Here that means the motif's
    plasmids fall into two groups -- destroyed and untouched -- which is the signature of a
    motif that is really a diluted version of a different site, or of something wrong with the
    data. Returns NaN below four values, where it is not defined.
    """
    v = np.asarray(values, dtype=float)
    v = v[np.isfinite(v)]
    n = len(v)
    if n < 4 or np.allclose(v, v[0]):
        return float("nan")
    g = skew(v, bias=False)
    k = kurtosis(v, bias=False, fisher=True)
    denom = k + 3.0 * (n - 1) ** 2 / ((n - 2) * (n - 3))
    return float((g ** 2 + 1.0) / denom) if denom > 0 else float("nan")


BIMODALITY_BENCHMARK = 5.0 / 9.0


def annotate_significance(results_df, log2fc_series, left_context, right_context,
                          all_pvalues=None, log2fc_thr=-1, q_threshold=0.05, encoded=None):
    """Add p_value, q_value, called and bimodality to a result table.

    `all_pvalues` are the p-values of every motif the scan tested, which is what the
    Benjamini-Hochberg correction has to be computed over -- correcting only over the handful
    that survived filtering would be meaningless.

    Nothing is removed. `called` marks the rows that clear `q_threshold`; the rest stay in the
    table so that a weak result is visible as a weak claim rather than silently absent.
    """
    if results_df is None:
        return results_df
    if results_df.empty:
        # A strain with no active system is the first thing a new user runs, so the empty
        # table must have the same columns as a full one -- otherwise `flex[flex.called]`
        # works on every strain that finds something and raises on the ones that do not.
        out = results_df.copy()
        for _c, _dt in (("p_value", float), ("q_value", float),
                        ("called", bool), ("bimodality", float), ("bimodal", bool)):
            if _c not in out.columns:
                out[_c] = pd.Series(dtype=_dt)
        return out
    out = results_df.copy()
    # The null is this sample's own background depletion rate, and the correction runs over
    # every motif the scan tested, not just the survivors. Both are in `01_utils`.
    rate = background_depletion_rate(log2fc_series, log2fc_thr)

    p = motif_pvalues(out["num_sequences"].to_numpy(),
                      out["fraction_depleted"].to_numpy(), rate)
    out["p_value"] = p
    if all_pvalues is not None and len(all_pvalues):
        # The reported motifs were tested by the scan, so their p-values are already in
        # `all_pvalues`; appending them again counted those tests twice. Only a p-value the scan
        # never produced is a new test and joins the pool. Each motif's q is then read off the
        # adjusted pool at its own p-value -- BH q-values are a non-decreasing step function of
        # p, so tied p-values share one q.
        pool = np.asarray(all_pvalues, dtype=float)
        pool = np.sort(np.concatenate([pool, p[~np.isin(p, pool)]]))
        q_pool = benjamini_hochberg(pool)
        out["q_value"] = q_pool[np.searchsorted(pool, p, side="right") - 1]
    else:
        out["q_value"] = benjamini_hochberg(p)
    out["called"] = out["q_value"] < q_threshold

    # Presence comes from the window codes, not a regex per sequence -- the same vectorized
    # path the rest of the pipeline uses. Motifs the fast path cannot encode fall back.
    motifs = out["motif"].tolist()
    if "pattern" in out.columns:
        patterns = []
        for pat in out["pattern"]:
            try:
                patterns.append(tuple(ast.literal_eval(pat)) if isinstance(pat, str) else tuple(pat))
            except (ValueError, SyntaxError):
                patterns.append(None)
    else:
        patterns = [None] * len(motifs)

    if encoded is None:
        encoded = encode_library(
            get_lib_seq_context(log2fc_series.index.tolist(), left_context, right_context))
    presence, handled = motif_presence_matrix(encoded, motifs, patterns)
    for j in np.flatnonzero(~handled):
        presence[:, j] = _get_filter_for_motif(
            log2fc_series, motifs[j], left_context, right_context).to_numpy()

    values = log2fc_series.to_numpy()
    out["bimodality"] = [bimodality_coefficient(values[presence[:, j]])
                         for j in range(len(motifs))]
    out["bimodal"] = out["bimodality"] > BIMODALITY_BENCHMARK

    return out.sort_values(["called", "q_value"], ascending=[False, True])

# %% ../nbs/00_core.ipynb #3bfb4529
class TooManyCandidatesError(RuntimeError):
    """Raised when the flexible-motif search produces more candidates than it will score.

    The candidate table is available as `.candidates` for inspection. A count this large
    usually means the thresholds are too loose for the sample, not that the strain has hundreds
    of sites.
    """

    def __init__(self, n_candidates, max_candidates, log2fc_thr, score_thr, min_support, candidates):
        self.n_candidates = n_candidates
        self.max_candidates = max_candidates
        self.candidates = candidates
        super().__init__(
            f"Too many candidate motifs: {n_candidates} > max_candidates={max_candidates}. "
            f"The unique-hit scoring step is O(N^2) and would not finish. This usually means the "
            f"thresholds are too permissive for this data. Try a stricter "
            f"flexible_motif_log2fc_thr (currently {log2fc_thr}, e.g. -0.8 or -1.0), "
            f"flexible_motif_score_thr (currently {score_thr}, e.g. 0.7 or 0.85), or "
            f"flexible_motif_min_support (currently {min_support}, e.g. 5 or 10). "
            f"Raise max_candidates only if you know why this strain has so many candidates. "
            f"The unfiltered candidates are on this exception as `.candidates`."
        )

# %% ../nbs/00_core.ipynb #006a8b89
def _canonicalise_flexible_motifs(df):
    """Put every motif in a flexible-motif result table on its canonical strand.

    A motif and its reverse complement have identical statistics, so rewriting the label loses
    nothing.
    """
    if df is None or df.empty or 'motif' not in df.columns:
        return df
    df = df.copy()
    flipped = df['motif'] != df['motif'].map(canonical_motif)
    df['motif'] = df['motif'].map(canonical_motif)
    # The pattern has to follow the motif. Reverse-complementing a (d1, spacer, d2) site gives
    # a (d2, spacer, d1) site, so a relabelled row whose pattern was left alone would describe
    # a string it does not hold -- and every consumer that pairs motif with pattern, such as
    # motif_presence_matrix, would silently decline to handle it.
    if 'pattern' in df.columns:
        def _mirror(p):
            try:
                d1, sp, d2 = ast.literal_eval(p) if isinstance(p, str) else tuple(p)
            except (ValueError, SyntaxError, TypeError):
                return p
            # With no spacer the site is contiguous and (k, 0, 0) is the spelling the
            # pattern list uses, so mirroring must not turn (6, 0, 0) into (0, 0, 6).
            m = (d1 + d2, 0, 0) if sp == 0 else (d2, sp, d1)
            return str(m) if isinstance(p, str) else m
        df.loc[flipped, 'pattern'] = df.loc[flipped, 'pattern'].map(_mirror)
    return df

# %% ../nbs/00_core.ipynb #27dcc30b
def identify_depleted_motifs_scanning_ends(log2fc_series,
                                           scan_depth_k=6,
                                           max_motif_length=4,
                                           depletion_threshold=-1,
                                           score_thr=0.85,
                                           min_sequence_support=5):
    """Motifs whose depletion is locked to a constant offset from one end of the insert.

    For every motif length up to `max_motif_length` and every offset up to `scan_depth_k` from
    each end, score the sequences carrying that exact substring at that exact offset.

    An offset is measured **from the anchoring end**, and the `anchor` column says which:
    `left` counts from the start of the insert, `right` from its end. That distinction is what
    makes the scan work on a library of ragged inserts -- an absolute index means a different
    thing in a long insert and a short one, so a right-hand motif keyed by absolute index is
    split across every length present and mostly lost below `min_sequence_support`.

    Only ACGT counts: a window containing any other character is skipped, as in the flexible
    scan. The forward strand only, because an offset is not meaningful on the other one.

    Returns one row per (motif, anchor, offset) with 'motif', 'anchor', 'position', 'length',
    'num_sequences', 'avg_log2fc' and 'fraction_depleted', keeping those with more than
    `min_sequence_support` sequences and `fraction_depleted >= score_thr`.
    """
    cols = ['motif', 'anchor', 'position', 'length', 'num_sequences',
            'avg_log2fc', 'fraction_depleted']
    if not isinstance(log2fc_series, pd.Series) or log2fc_series.empty:
        return pd.DataFrame(columns=cols)

    values = pd.to_numeric(log2fc_series, errors='coerce').to_numpy(dtype=float)
    seqs = list(log2fc_series.index)
    usable = np.array([isinstance(s, str) for s in seqs]) & np.isfinite(values)
    seqs = [s for s, ok in zip(seqs, usable) if ok]
    fc = values[usable]
    if not seqs:
        return pd.DataFrame(columns=cols)

    name = log2fc_series.name if log2fc_series.name else "input Series"
    print(f"Scanning motifs of length 1 to {max_motif_length} at offsets 0 to {scan_depth_k} "
          f"from each end, for {name}.")
    print(f"Minimum sequence support for a motif: > {min_sequence_support} "
          f"(i.e., {min_sequence_support + 1} or more)")

    width = max(len(s) for s in seqs)
    # Left-aligned, and right-aligned by padding on the LEFT with 'N'. Padding encodes to the
    # same out-of-alphabet code a non-ACGT base does, so a window that runs off a short
    # sequence is rejected by the very test that rejects an N -- no length bookkeeping.
    encodings = {'left': encode_library(seqs)[0],
                 'right': encode_library([s.rjust(width, 'N') for s in seqs])[0]}
    is_depleted = fc < depletion_threshold

    rows = []
    for length in range(1, max_motif_length + 1):
        n_codes = 4 ** length
        for anchor, arr in encodings.items():
            for offset in range(scan_depth_k + 1):
                start = offset if anchor == 'left' else arr.shape[1] - offset - length
                if start < 0 or start + length > arr.shape[1]:
                    continue
                window = arr[:, start:start + length]
                good = ~(window == 4).any(axis=1)
                if not good.any():
                    continue
                codes = np.zeros(window.shape[0], dtype=np.int64)
                for j in range(length):          # the window as a base-4 numeral
                    codes = codes * 4 + window[:, j]
                codes, kept_fc, kept_dep = codes[good], fc[good], is_depleted[good]
                n = np.bincount(codes, minlength=n_codes)
                n_dep = np.bincount(codes, weights=kept_dep, minlength=n_codes)
                fc_sum = np.bincount(codes, weights=kept_fc, minlength=n_codes)
                enough = np.flatnonzero(n > min_sequence_support)
                if not len(enough):
                    continue
                selected = enough[(n_dep[enough] / n[enough]) >= score_thr]
                if not len(selected):
                    continue
                for motif, cnt, dep, total in zip(decode_motif_codes(selected, (length, 0, 0)),
                                                  n[selected], n_dep[selected], fc_sum[selected]):
                    rows.append({'motif': motif, 'anchor': anchor, 'position': offset,
                                 'length': length, 'num_sequences': int(cnt),
                                 'avg_log2fc': float(total / cnt),
                                 'fraction_depleted': float(dep / cnt)})
    if not rows:
        print("No motifs met the support and score thresholds.")
        return pd.DataFrame(columns=cols)
    return (pd.DataFrame(rows, columns=cols)
            .sort_values(['fraction_depleted', 'avg_log2fc', 'num_sequences'],
                         ascending=[False, True, False])
            .reset_index(drop=True))

# %% ../nbs/00_core.ipynb #b9dc539f
def _contains_at(core, candidate):
    """Where `core` sits inside `candidate`, or None -- both given as (motif, anchor, offset).

    Containment is only meaningful within one anchor, and the arithmetic differs between them:
    a left-anchored motif grows rightwards from its offset, a right-anchored one grows
    leftwards, so the same core sits at a different index in the longer string.
    """
    (c_motif, c_anchor, c_pos), (k_motif, k_anchor, k_pos) = core, candidate
    if c_anchor != k_anchor or len(c_motif) >= len(k_motif):
        return None
    if c_anchor == 'left':
        expected = c_pos - k_pos
    else:
        expected = len(k_motif) + k_pos - len(c_motif) - c_pos
    if 0 <= expected <= len(k_motif) - len(c_motif) and \
            k_motif[expected:expected + len(c_motif)] == c_motif:
        return expected
    return None


def filter_to_core_motifs(depleted_motifs_df, score_improvement_margin=0.05):
    """Reduce each family of nested fixed-position motifs to its core.

    Having found `GTG` at an offset, the scan also finds `GTGA` and `CGTGA` at the same place.
    A longer motif is kept only if the extra base **earns its place** -- raises the depletion
    fraction by more than `score_improvement_margin`. On a real call the core is already at or
    near 1.0, so in practice this prefers the shortest description that clears the threshold,
    which is what an explainer wants: the shortest one names the most plasmids.
    """
    if depleted_motifs_df.empty:
        return pd.DataFrame(columns=depleted_motifs_df.columns)

    sorted_df = depleted_motifs_df.sort_values(
        by=['length', 'fraction_depleted', 'motif'],
        ascending=[True, False, True]).reset_index(drop=True)
    if 'anchor' not in sorted_df.columns:
        sorted_df = sorted_df.assign(anchor='left')

    cores = []
    for _, candidate in sorted_df.iterrows():
        key = (candidate['motif'], candidate.get('anchor', 'left'), int(candidate['position']))
        subsumed = False
        for core in cores:
            if _contains_at((core['motif'], core.get('anchor', 'left'),
                             int(core['position'])), key) is None:
                continue
            if not candidate['fraction_depleted'] > core['fraction_depleted'] + score_improvement_margin:
                subsumed = True
                break
        if not subsumed:
            cores.append(candidate.to_dict())
    return pd.DataFrame(cores) if cores else pd.DataFrame(columns=depleted_motifs_df.columns)

# %% ../nbs/00_core.ipynb #a132cf05
def unexplained_fixed_motifs(fixed_motifs_df, reported_motifs_df, log2fc_series,
                             left_context, right_context, log2fc_thr=-1,
                             score_thr=0.7, min_support=3, encoded=None):
    """Fixed-position motifs whose depletion no reported flexible motif accounts for.

    A fixed motif `F` is explained by a reported motif `M` when the plasmids carrying `F`
    but not `M` no longer deplete. One that survives every reported motif has no owner.

    Returns a DataFrame with the fixed motif's own evidence, empty when everything is
    accounted for.
    """
    empty = pd.DataFrame(columns=['motif', 'anchor', 'position', 'length',
                                  'num_sequences', 'fraction_depleted', 'avg_log2fc'])
    if fixed_motifs_df is None or len(fixed_motifs_df) == 0:
        return empty

    fixed_pres = fixed_motif_presence(log2fc_series, fixed_motifs_df)
    fc = log2fc_series.to_numpy()

    if reported_motifs_df is None or len(reported_motifs_df) == 0:
        rep = np.zeros((len(fc), 0), dtype=bool)
    else:
        patterns = []
        for p in reported_motifs_df.get('pattern', [None] * len(reported_motifs_df)):
            try:
                patterns.append(tuple(ast.literal_eval(p)) if isinstance(p, str) else tuple(p))
            except (ValueError, SyntaxError, TypeError):
                patterns.append(None)
        if encoded is None:
            encoded = encode_library(
                get_lib_seq_context(log2fc_series.index.tolist(), left_context, right_context))
        rep, handled = motif_presence_matrix(
            encoded, reported_motifs_df['motif'].tolist(), patterns)
        for j in np.flatnonzero(~handled):
            rep[:, j] = _get_filter_for_motif(
                log2fc_series, reported_motifs_df['motif'].iloc[j],
                left_context, right_context).to_numpy()

    rows = []
    for j, row in enumerate(fixed_motifs_df.itertuples()):
        owned = False
        for k in range(rep.shape[1]):
            alone = fixed_pres[:, j] & ~rep[:, k]
            n = int(alone.sum())
            still = float((fc[alone] < log2fc_thr).mean()) if n else 0.0
            if n < min_support or still < score_thr:
                owned = True
                break
        if not owned:
            carriers = fc[fixed_pres[:, j]]
            rows.append(dict(motif=row.motif, anchor=getattr(row, 'anchor', 'left'),
                             position=int(row.position),
                             length=int(row.length), num_sequences=len(carriers),
                             fraction_depleted=float((carriers < log2fc_thr).mean())
                             if len(carriers) else 0.0,
                             avg_log2fc=float(carriers.mean()) if len(carriers) else float('nan')))
    return pd.DataFrame(rows) if rows else empty


def _warn_unexplained_fixed(fixed_motifs_df, reported_motifs_df, log2fc_series,
                            left_context, right_context, log2fc_thr, score_thr, min_support,
                            encoded=None):
    """Warn, with evidence, about position-locked depletion that nothing reported explains."""
    orphans = unexplained_fixed_motifs(fixed_motifs_df, reported_motifs_df, log2fc_series,
                                       left_context, right_context, log2fc_thr=log2fc_thr,
                                       score_thr=score_thr, min_support=min_support,
                                       encoded=encoded)
    if len(orphans) == 0:
        return orphans
    lines = [f"    {r.motif} at offset {r.position} from the "
             f"{getattr(r, 'anchor', 'left')}: n={r.num_sequences}, "
             f"score={r.fraction_depleted:.2f}, mean log2FC={r.avg_log2fc:.2f}"
             for r in orphans.itertuples()]
    warnings.warn(
        "Position-locked depletion that no reported motif explains:\n" + "\n".join(lines) +
        "\nA junction-formed site whose shape IS in the scanned pattern space is normally "
        "found by the flexible scan, which then accounts for these plasmids. Consider widening "
        "flexible_motif_patterns (a longer spacer or a different half-site length), or check "
        "whether something other than a recognition site depletes at this offset.",
        stacklevel=3)
    return orphans

# %% ../nbs/00_core.ipynb #e7d6ec42
def find_restricted_motifs(log2fc_series,
                           left_context_str,
                           right_context_str,
                           n_jobs=1,
                           fixed_motif_scan_depth_k=6,
                           fixed_motif_max_length=4,
                           fixed_motif_depletion_thr=None,
                           fixed_motif_score_thr=0.85,
                           fixed_motif_min_support=5,
                           core_motif_score_margin=0.05,
                           flexible_motif_patterns=None,
                           flexible_motif_log2fc_thr=-1,
                           flexible_motif_min_support=5,
                           flexible_motif_score_thr=0.5,
                           max_candidates=150,
                           q_threshold=0.05,
                           encoded_library=None
                           ):
    """
    Full pipeline to identify fixed-position core motifs and then
    position-independent motifs in the remaining sequences.

    The fixed-position scan runs first; it does not remove any sequence. Every flexible
    pattern is then scanned over the whole library with its flanking context, the two-way
    filter_redundant_patterns is applied once over all candidates, step 4 drops candidates
    whose depletion a stronger motif -- flexible or fixed-position -- already accounts for, and
    the survivors are rescored on unique hits.

    A fixed motif at a sequence end is usually a flexible motif straddling the library context
    (JJ1886's GTG at position 0 is ATACNNNNGTG, with ATAC in the left context), so the flexible
    scan finds it directly. One that no reported motif explains is raised as a warning, because
    it means the site's shape was probably never tested.

    Args:
        n_jobs (int): processes used to scan the flexible patterns. 1 (default) runs in this
            process. With the vectorized scan a pattern takes about a second on a 30k-sequence
            library, so more is rarely worth the startup cost.
        flexible_motif_min_support (int): minimum plasmids for a motif to be considered. The
            default of 5 is set by a permutation test rather than by taste: on the smaller
            example library, motifs with 3-4 supporting plasmids arise by chance about once per
            scan (0.8 measured over 20 permutations, 0.60 expected analytically), and none at
            all arise at 5 or above. It cannot go higher than about 6 without deleting a real
            call -- BsaI on JJ1886 has only 6 supporting plasmids there.
        fixed_motif_depletion_thr (float): log2FC below which a sequence counts as depleted in
            the fixed-position scan. Defaults to `flexible_motif_log2fc_thr`, so the two scans
            agree on what depletion means; pass a value to decouple them.
        q_threshold (float): a motif is marked `called` when its Benjamini-Hochberg q-value,
            computed against this sample's own background depletion rate and over every motif
            the scan tested, falls below this. Motifs that do not clear it are still returned,
            flagged, rather than dropped.
        flexible_motif_patterns (list): the architectures to search, as `(d1, spacer, d2)`.
            Defaults to `get_patterns()`. Each is rewritten to its `canonical_pattern` and
            duplicates dropped, so `(4, 4, 3)` is searched as `(3, 4, 4)` and never twice.
        flexible_motif_score_thr (float): a candidate needs at least this fraction of its
            plasmids depleted. Default 0.5, the value used in the paper.
        encoded_library (tuple): `encode_library(get_lib_seq_context(log2fc_series.index,
            left_context_str, right_context_str))`, if the caller already has it. Strains
            screened with the same library and flanks share it, so a panel encodes it once.
            It must describe exactly `log2fc_series.index`, in order.
        max_candidates (int): Safety limit on the number of candidate flexible
            motifs before entering the O(N²) update_motif_scores_from_unique_hits
            step.  If more candidates are found the function aborts that step,
            prints guidance on tightening thresholds, and returns the raw
            (unfiltered) candidates so the caller can inspect them.
            Default: 150.
    """
    # The fixed scan's threshold tracks the flexible one unless the caller sets it, so both
    # scans agree on what "depleted" means. Pinned independently, it would go blind whenever a
    # caller lowers flexible_motif_log2fc_thr for a weakly-interfering system -- and step 4
    # would lose its explainer in exactly the permissive regime where borrowed scores are most
    # common.
    if fixed_motif_depletion_thr is None:
        fixed_motif_depletion_thr = flexible_motif_log2fc_thr

    print("--- Starting Fixed-Position Motif Analysis (on original short sequences) ---")
    depleted_fixed_motifs_df = identify_depleted_motifs_scanning_ends(
        log2fc_series,
        scan_depth_k=fixed_motif_scan_depth_k,
        max_motif_length=fixed_motif_max_length,
        depletion_threshold=fixed_motif_depletion_thr,
        score_thr=fixed_motif_score_thr,
        min_sequence_support=fixed_motif_min_support
    )
    core_fixed_motifs_df = filter_to_core_motifs(
        depleted_fixed_motifs_df,
        score_improvement_margin=core_motif_score_margin
    )
    del depleted_fixed_motifs_df

    if core_fixed_motifs_df.empty:
        print("No core motifs found at fixed positions.")
    else:
        print(f"Found {len(core_fixed_motifs_df)} core motifs at fixed positions:")
        for _, row in core_fixed_motifs_df.iterrows():
            print(f"  - Fixed Motif: {row['motif']}, Pos: {row['position']}, Len: {row['length']}, FracDep: {row['fraction_depleted']:.2f}, AvgFC: {row['avg_log2fc']:.2f}, N: {row['num_sequences']}")

    print("\n--- Starting Position-Independent Motif Analysis (with context) ---")
    # This scan does NOT consume the fixed-position result: it runs on the full library, from
    # the same log2FC table the fixed scan read. The two are independent branches and meet
    # only at step 4, where a fixed-position motif may explain a flexible candidate away.
    if log2fc_series.empty:
        print("The input series is empty; there is nothing to scan.")
        flexible_motifs_results_df = pd.DataFrame(columns=['motif', 'pattern', 'fraction_depleted', 'num_sequences', 'avg_log2fc'])
        # No pattern was scanned, so no test was performed: an empty p-value set, not the
        # not-yet-assigned tested_pvalues from the scan below.
        _final = annotate_significance(
            _canonicalise_flexible_motifs(flexible_motifs_results_df),
            log2fc_series, left_context_str, right_context_str,
            all_pvalues=np.array([]), log2fc_thr=flexible_motif_log2fc_thr,
            q_threshold=q_threshold)
        _warn_unexplained_fixed(core_fixed_motifs_df, _final, log2fc_series,
                                left_context_str, right_context_str,
                                flexible_motif_log2fc_thr, flexible_motif_score_thr,
                                flexible_motif_min_support)
        return core_fixed_motifs_df, _final

    # The library is encoded once and every step below reads it.
    if encoded_library is None:
        encoded_library = encode_library(get_lib_seq_context(
            log2fc_series.index.tolist(), left_context_str, right_context_str))
    elif encoded_library[0].shape[0] != len(log2fc_series):
        raise ValueError(
            f"encoded_library holds {encoded_library[0].shape[0]} sequences but log2fc_series "
            f"has {len(log2fc_series)}; it must encode exactly this series' index, in order, "
            f"with these flanks.")
    fc_values_for_flexible_analysis = log2fc_series.to_numpy(dtype=float)

    cumulative_flexible_motifs_df = pd.DataFrame()

    if flexible_motif_patterns is None:
        flexible_motif_patterns = get_patterns()
    if not isinstance(flexible_motif_patterns, list):
        print("Warning: flexible_motif_patterns should be a list. Wrapping it in a list.")
        flexible_motif_patterns = [flexible_motif_patterns]

    # A pattern and its mirror find the same sites (the scan reads both strands), and a gapless
    # pattern is one run however it is split, so each is searched once, in canonical form.
    rewritten = sorted({(tuple(p), canonical_pattern(p)) for p in flexible_motif_patterns
                        if tuple(p) != canonical_pattern(p)})
    for p, c in rewritten:
        print(f"Pattern {p} is searched as {c}: the same sites, read on the other strand.")
    flexible_motif_patterns = sorted({canonical_pattern(p) for p in flexible_motif_patterns},
                                     key=lambda x: (x[0] + x[2], x[1], x))

    if n_jobs == 1:
        per_pattern = [
            process_single_flexible_pattern(
                p, encoded_library, fc_values_for_flexible_analysis,
                flexible_motif_log2fc_thr, flexible_motif_score_thr,
                flexible_motif_min_support)
            for p in tqdm(flexible_motif_patterns, desc="Scanning patterns")
        ]
    else:
        worker = functools.partial(
            process_single_flexible_pattern,
            encoded_library=encoded_library,
            fc_values_for_flexible_analysis=fc_values_for_flexible_analysis,
            flexible_motif_log2fc_thr=flexible_motif_log2fc_thr,
            flexible_motif_score_thr=flexible_motif_score_thr,
            flexible_motif_min_support=flexible_motif_min_support,
            # Each worker scans single-threaded: n_jobs processes each starting numba's
            # thread pool would ask for n_jobs x cores at once, and a forked child never has
            # to touch a thread pool its parent may have started.
            parallel=False)
        with Pool(processes=n_jobs) as pool:
            # imap preserves pattern order, so the result does not depend on which worker
            # finishes first.
            per_pattern = list(tqdm(pool.imap(worker, flexible_motif_patterns),
                                    total=len(flexible_motif_patterns),
                                    desc="Scanning patterns"))

    tested_pvalues = (np.concatenate([pv for _, pv, _ in per_pattern]) if per_pattern
                      else np.array([]))
    hits = [df for df, _, _ in per_pattern if not df.empty]
    # Step 3 scores variants from the same counts; a pattern step 2 scanned is never rescanned.
    totals = {p: t for p, (_, _, t) in zip(flexible_motif_patterns, per_pattern)}
    if hits:
        # Every pattern is scanned first and the redundancy filter runs once over all
        # candidates, rather than after each pattern. Filtering incrementally made the
        # outcome depend on the order patterns were scanned in; with the filter now
        # order-independent the two agree, and doing it once is simpler and faster.
        cumulative_flexible_motifs_df = filter_redundant_patterns(
            pd.concat(hits, ignore_index=True), log2fc_series,
            left_context_str, right_context_str,
            log2fc_thr=flexible_motif_log2fc_thr,
            score_thr=flexible_motif_score_thr,
            min_support=flexible_motif_min_support,
            encoded=encoded_library, totals=totals,
        )
        print(f"{sum(len(h) for h in hits)} candidate(s) across all patterns; "
              f"{len(cumulative_flexible_motifs_df)} remain after redundancy filtering.")

    if cumulative_flexible_motifs_df.empty:
        print(f"\nNo flexible motifs found with support >= {flexible_motif_min_support} and score >= {flexible_motif_score_thr} for any provided pattern.")
        flexible_motifs_results_df = pd.DataFrame(columns=['motif', 'pattern', 'fraction_depleted', 'num_sequences', 'avg_log2fc'])
    else:
        cumulative_flexible_motifs_df, _explained = filter_explained_candidates(
            cumulative_flexible_motifs_df, log2fc_series, left_context_str, right_context_str,
            log2fc_thr=flexible_motif_log2fc_thr, score_thr=flexible_motif_score_thr,
            min_support=flexible_motif_min_support,
            fixed_motifs_df=core_fixed_motifs_df, encoded=encoded_library)
        if _explained:
            print(f"{len(_explained)} candidate(s) whose score was borrowed:")
            for _m, (_by, _n, _s) in sorted(_explained.items()):
                print(f"    {_m} <- {_by} (without them: n={_n}, score={_s:.2f})")

        n_candidates = len(cumulative_flexible_motifs_df)

        if n_candidates > max_candidates:
            raise TooManyCandidatesError(
                n_candidates,
                max_candidates,
                flexible_motif_log2fc_thr,
                flexible_motif_score_thr,
                flexible_motif_min_support,
                cumulative_flexible_motifs_df,
            )

        flexible_motifs_results_df = cumulative_flexible_motifs_df

        # Canonicalise before reporting, so the names printed here are the names in the
        # returned table. A motif and its reverse complement are the same site, and the scan
        # may have found either; a user who reads GAGACC in the log and then looks for it in
        # the results would not find it, because the result says GGTCTC.
        flexible_motifs_results_df = _canonicalise_flexible_motifs(flexible_motifs_results_df)

        print(f"\n{len(flexible_motifs_results_df)} motifs remaining:")
        if flexible_motifs_results_df.empty:
            print("No core flexible motifs remained after filtering.")
        else:
            for _, row in flexible_motifs_results_df.iterrows():
                print(f"{row['motif']} (from pattern {row['pattern']}), FracDep: {row['fraction_depleted']:.2f}, AvgFC: {row['avg_log2fc']:.2f}, N: {row['num_sequences']}")

    final_table = annotate_significance(
            flexible_motifs_results_df,
            log2fc_series, left_context_str, right_context_str,
            all_pvalues=tested_pvalues, log2fc_thr=flexible_motif_log2fc_thr,
            q_threshold=q_threshold, encoded=encoded_library)
    _warn_unexplained_fixed(core_fixed_motifs_df, final_table, log2fc_series,
                            left_context_str, right_context_str,
                            flexible_motif_log2fc_thr, flexible_motif_score_thr,
                            flexible_motif_min_support, encoded=encoded_library)
    return core_fixed_motifs_df, final_table

# %% ../nbs/00_core.ipynb #aa1c8f82
def find_restricted_motifs_mp(*args, cpu_count=1, **kwargs):
    """Deprecated alias for `find_restricted_motifs`; pass `n_jobs` instead of `cpu_count`.

    Provided so that scripts written against the older two-function API keep working; it
    forwards every argument unchanged. New code should call
    `find_restricted_motifs(..., n_jobs=...)`.
    """
    warnings.warn(
        "find_restricted_motifs_mp is deprecated; call find_restricted_motifs(..., "
        "n_jobs=...) instead. cpu_count is forwarded to n_jobs.",
        DeprecationWarning, stacklevel=2)
    return find_restricted_motifs(*args, n_jobs=cpu_count, **kwargs)

# %% ../nbs/00_core.ipynb #33631ba9
def filter_sequences_without_core_motifs(log2fc_series, core_motifs_df):
    """
    Filters an original log2fc Series to remove sequences that contain 
    any of the specified core motifs.

    Not part of the pipeline, which scans the whole library rather than setting any of it
    aside. Provided because selecting the sequences that do *not* carry a given fixed motif is
    a reasonable thing to want by hand.

    Args:
        log2fc_series (pd.Series): Series with sequences as its index and log2FC values.
        core_motifs_df (pd.DataFrame): DataFrame of core motifs, must include
                                       'motif', 'position', and 'length' columns.

    Returns:
        pd.Series: A new Series containing only sequences (and their log2FC values)
                   from log2fc_series that do not carry any of the core motifs.
    """
    if not isinstance(log2fc_series, pd.Series) or log2fc_series.empty:
        # print("Info: log2fc_series is empty or not a Series. Returning a copy.")
        return log2fc_series.copy() 
    
    expected_core_motif_cols = ['motif', 'position', 'length']
    if not isinstance(core_motifs_df, pd.DataFrame) or core_motifs_df.empty or \
       not all(col in core_motifs_df.columns for col in expected_core_motif_cols):
        print("Info: core_motifs_df is empty or invalid for filtering. Returning original log2fc_series.")
        return log2fc_series.copy()

    # Create a boolean mask, True for sequences to keep
    sequences_to_keep_mask = pd.Series(True, index=log2fc_series.index)

    # Iterate through each unique sequence string in the original Series' index
    # Using .loc for assignment to the mask handles duplicate indices in the original Series correctly
    for seq_str_to_check in log2fc_series.index.unique(): 
        if not isinstance(seq_str_to_check, str): 
            continue # Skip if index label is not a string
        
        # Check this sequence against all core motifs
        for _, motif_row in core_motifs_df.iterrows():
            motif_str = motif_row['motif']
            try:
                position = int(motif_row['position'])
                motif_len = int(motif_row['length'])
            except (ValueError, TypeError):
                # print(f"Warning: Invalid position/length for motif {motif_str} in core_motifs_df. Skipping this motif.")
                continue 

            if not isinstance(motif_str, str) or not motif_str: 
                continue

            anchor = motif_row['anchor'] if 'anchor' in core_motifs_df.columns else 'left'
            if len(seq_str_to_check) >= position + motif_len:
                here = (seq_str_to_check[position:position + motif_len] if anchor == 'left'
                        else seq_str_to_check[len(seq_str_to_check) - position - motif_len:
                                              len(seq_str_to_check) - position])
                if here == motif_str:
                    # If a motif is found, mark all occurrences of this sequence string for removal
                    sequences_to_keep_mask.loc[log2fc_series.index == seq_str_to_check] = False 
                    break # Move to the next unique sequence_str_to_check

    return log2fc_series[sequences_to_keep_mask]
